using IntelligentPersonalHealthOptimization.Models;
using IntelligentPersonalHealthOptimization.Models.Enums;
using SQLite;

namespace IntelligentPersonalHealthOptimization.Data;

public static partial class SeedData
{
    public static async Task SeedFoodsAsync(SQLiteAsyncConnection connection)
    {
        var allFoods = GetFoodLibrary();
        var count = await connection.Table<Food>().CountAsync();
        if (count == 0)
        {
            await connection.InsertAllAsync(allFoods);
            return;
        }

        // Incremental: only insert foods that don't already exist
        var existingNames = (await connection.Table<Food>().ToListAsync())
            .Select(f => f.Name).ToHashSet(StringComparer.OrdinalIgnoreCase);
        var newFoods = allFoods.Where(f => !existingNames.Contains(f.Name)).ToList();
        if (newFoods.Count > 0)
            await connection.InsertAllAsync(newFoods);
    }

